3	// MARK: - The curves (spec §11 GR-12, grading-2 G2-3; GR-32, grading-4 T4-2)
4	
5	/// One curve point, `[x, y]` in JSON (`model_grade.rs`'s `CurvePoint`): the
6	/// input and the output, each 0…1.
7	struct CurvePoint: Hashable, Codable {
8	    var x: Double
9	    var y: Double
10	
11	    init(x: Double, y: Double) {
12	        self.x = x
13	        self.y = y
14	    }
15	
16	    init(from decoder: Decoder) throws {
17	        var c = try decoder.unkeyedContainer()
18	        x = try c.decode(Double.self)
19	        y = try c.decode(Double.self)
20	    }
21	
22	    func encode(to encoder: Encoder) throws {
23	        var c = encoder.unkeyedContainer()
24	        try c.encode(x)
25	        try c.encode(y)
26	    }
27	}
28	
29	/// What a channel's numbers mean (spec §11 GR-32, `model_grade.rs`'s
30	/// `CurveDomain`): a tone curve maps 0…1 to 0…1; a hue curve maps a hue in
31	/// degrees (periodic, 0 ≤ x < 360) to a shift in degrees (−180…180, 0 none)
32	/// or a gain (0…2, 1 none). Everything the editor, the fields and the strip
33	/// need to treat the three alike.
34	enum CurveDomain: Equatable {
35	    case tone, hueShift, hueGain
36	
37	    /// The lowest point a point may take (x, then y).
38	    var lower: CurvePoint {
39	        switch self {
40	        case .tone: return CurvePoint(x: 0, y: 0)
41	        case .hueShift: return CurvePoint(x: 0, y: -180)
42	        case .hueGain: return CurvePoint(x: 0, y: 0)
43	        }
44	    }
45	
46	    /// The highest point a point may take: a hue point stops at 359.9, below
47	    /// the wrap (owner choice 6).
48	    var upper: CurvePoint {
49	        switch self {
50	        case .tone: return CurvePoint(x: 1, y: 1)
51	        case .hueShift: return CurvePoint(x: 359.9, y: 180)
52	        case .hueGain: return CurvePoint(x: 359.9, y: 2)
53	        }
54	    }
55	
56	    /// The plot's axes from `lower`: x across, y up.
57	    var span: CurvePoint {
58	        switch self {
59	        case .tone: return CurvePoint(x: 1, y: 1)
60	        case .hueShift: return CurvePoint(x: 360, y: 360)
61	        case .hueGain: return CurvePoint(x: 360, y: 2)
62	        }
63	    }
64	
65	    /// The x period: none for a tone curve, a turn for a hue curve.
66	    var period: Double? { self == .tone ? nil : 360 }
67	
68	    /// The value that changes nothing: none for a tone curve (y = x).
69	    var neutral: Double? {
70	        switch self {
71	        case .tone: return nil
72	        case .hueShift: return 0
73	        case .hueGain: return 1
74	        }
75	    }
76	
77	    /// How close a dragged point may come to a neighbour's x.
78	    var minGap: Double { self == .tone ? 0.001 : 0.1 }
79	
80	    /// An arrow key's step, and ⇧'s (owner choice 7).
81	    var nudge: CurvePoint {
82	        switch self {
83	        case .tone: return CurvePoint(x: 0.01, y: 0.01)
84	        case .hueShift: return CurvePoint(x: 1, y: 1)
85	        case .hueGain: return CurvePoint(x: 1, y: 0.01)
86	        }
87	    }
88	
89	    var bigNudge: CurvePoint {
90	        switch self {
91	        case .tone: return CurvePoint(x: 0.1, y: 0.1)
92	        case .hueShift: return CurvePoint(x: 10, y: 10)
93	        case .hueGain: return CurvePoint(x: 10, y: 0.1)
94	        }
95	    }
96	
97	    /// The identity's shortest spelling, as the core writes an absent
98	    /// channel: `[[0, 0], [1, 1]]`, `[[0, 0], [180, 0]]`, `[[0, 1], [180, 1]]`.
99	    var identity: [CurvePoint] {
100	        switch self {
101	        case .tone: return ColorCurves.identityCurve
102	        case .hueShift: return [CurvePoint(x: 0, y: 0), CurvePoint(x: 180, y: 0)]
103	        case .hueGain: return [CurvePoint(x: 0, y: 1), CurvePoint(x: 180, y: 1)]
104	        }
105	    }
106	
107	    /// The core's identity: a tone curve's `ColorCurves.isIdentity`; a hue
108	    /// curve with a point whose every value is the neutral, whatever its x's.
109	    func isIdentity(_ points: [CurvePoint]) -> Bool {
110	        guard let neutral else { return ColorCurves.isIdentity(points) }
111	        return !points.isEmpty && points.allSatisfy { $0.y == neutral }
112	    }
113	}
114	
115	/// The six curves in the model's order: each one's picker title (and undo
116	/// "Reset <Title>") and its ink — the master's and the hue curves' the
117	/// strong text colour, each colour's the parade's tint.
118	enum CurveChannel: String, CaseIterable {
119	    case master, red, green, blue, hueHue = "hue_hue", hueSat = "hue_sat"
120	
121	    var title: String {
122	        switch self {
123	        case .hueHue: return "Hue"
124	        case .hueSat: return "Sat"
125	        default: return rawValue.capitalized
126	        }
127	    }
128	
129	    var domain: CurveDomain {
130	        switch self {
131	        case .master, .red, .green, .blue: return .tone
132	        case .hueHue: return .hueShift
133	        case .hueSat: return .hueGain
134	        }
135	    }
136	
137	    var tint: NSColor {
138	        let index: Int
139	        switch self {
140	        case .master, .hueHue, .hueSat: return DS.textStrong
141	        case .red: index = 0
142	        case .green: index = 1
143	        case .blue: index = 2
144	        }
145	        let (r, g, b) = ParadeView.tints[index]
146	        return NSColor(srgbRed: r, green: g, blue: b, alpha: 1)
147	    }
148	}
149	
150	/// A channel blended inside an action (spec §11 GR-34): the recipe's and
151	/// `clip_state`'s `{"from": [[x, y], …], "to": [[x, y], …], "t": t}` for two
152	/// non-identity curves of different point counts, drawn as
153	/// `(1 − t)·from(x) + t·to(x)` by the strip. Never in a file.
154	struct CurveBlend: Hashable, Decodable {
155	    let from: [CurvePoint]
156	    let to: [CurvePoint]
157	    let t: Double
158	}
159	
160	/// `video.curves`: the four tone curves and the two hue curves (spec §11
161	/// GR-32), each a list of 2–16 points with x strictly rising. Read
162	/// leniently: an absent, null or malformed channel is its domain's identity,
163	/// as the core writes an absent one. A blended channel (GR-34) holds its
164	/// `from` points, with the blend in `blends`; a malformed blend is the
165	/// identity. `blends` is never encoded.
166	struct ColorCurves: Codable, Hashable {
167	    let master: [CurvePoint]
168	    let red: [CurvePoint]
169	    let green: [CurvePoint]
170	    let blue: [CurvePoint]
171	    let hueHue: [CurvePoint]
172	    let hueSat: [CurvePoint]
173	    /// The channels blended at this instant, each with its two lists and t.
174	    let blends: [CurveChannel: CurveBlend]
175	
176	    private enum CodingKeys: String, CodingKey {
177	        case master, red, green, blue, hueHue, hueSat
178	    }
179	
180	    /// The tone identity's shortest spelling, `[[0, 0], [1, 1]]`.
181	    static let identityCurve = [CurvePoint(x: 0, y: 0), CurvePoint(x: 1, y: 1)]
182	
183	    init(
184	        master: [CurvePoint] = identityCurve, red: [CurvePoint] = identityCurve,
185	        green: [CurvePoint] = identityCurve, blue: [CurvePoint] = identityCurve,
186	        hueHue: [CurvePoint] = CurveDomain.hueShift.identity,
187	        hueSat: [CurvePoint] = CurveDomain.hueGain.identity,
188	        blends: [CurveChannel: CurveBlend] = [:]
189	    ) {
190	        self.master = master
191	        self.red = red
192	        self.green = green
193	        self.blue = blue
194	        self.hueHue = hueHue
195	        self.hueSat = hueSat
196	        self.blends = blends
197	    }
198	
199	    init(from decoder: Decoder) throws {
200	        let c = try decoder.container(keyedBy: CodingKeys.self)
201	        var blends: [CurveChannel: CurveBlend] = [:]
202	        func channel(_ key: CodingKeys, _ name: CurveChannel) -> [CurvePoint] {
203	            let domain = name.domain
204	            if let blend: CurveBlend = c.lenient(key) {
205	                guard blend.from.count >= 2, blend.to.count >= 2, blend.t.isFinite else {
206	                    return domain.identity
207	                }
208	                blends[name] = CurveBlend(from: blend.from, to: blend.to, t: min(max(blend.t, 0), 1))
209	                return blend.from
210	            }
211	            let points: [CurvePoint] = c.lenient(key, domain.identity)
212	            return points.count >= 2 ? points : domain.identity
213	        }
214	        master = channel(.master, .master)
215	        red = channel(.red, .red)
216	        green = channel(.green, .green)
217	        blue = channel(.blue, .blue)
218	        hueHue = channel(.hueHue, .hueHue)
219	        hueSat = channel(.hueSat, .hueSat)
220	        self.blends = blends
221	    }
222	
223	    static let identity = ColorCurves()
224	
225	    /// The core's `curve_is_identity` for a TONE curve: first x 0, last x 1,
226	    /// every y = x. A channel's own test is `channel.domain.isIdentity`.
227	    static func isIdentity(_ curve: [CurvePoint]) -> Bool {
228	        guard let first = curve.first, let last = curve.last else { return false }
229	        return first.x == 0 && last.x == 1 && curve.allSatisfy { $0.y == $0.x }
230	    }
231	
232	    /// The four tone curves all the identity and none blended:
233	    /// `curvesEnabled` is 0.
234	    var toneIsIdentity: Bool {
235	        [CurveChannel.master, .red, .green, .blue].allSatisfy {
236	            blends[$0] == nil && Self.isIdentity(points($0))
237	        }
238	    }
239	
240	    /// Both hue curves the identity and neither blended: `hueCurvesEnabled`
241	    /// is 0.
242	    var hueIsIdentity: Bool {
243	        blends[.hueHue] == nil && blends[.hueSat] == nil
244	            && CurveDomain.hueShift.isIdentity(hueHue) && CurveDomain.hueGain.isIdentity(hueSat)
245	    }
246	
247	    /// All six the identity: the strip is the placeholder.
248	    var isIdentity: Bool { toneIsIdentity && hueIsIdentity }
249	
250	    func points(_ channel: CurveChannel) -> [CurvePoint] {
251	        switch channel {
252	        case .master: return master
253	        case .red: return red
254	        case .green: return green
255	        case .blue: return blue
256	        case .hueHue: return hueHue
257	        case .hueSat: return hueSat
258	        }
259	    }
260	}
261	
262	/// What a curve write SENDS: the channels it names, each a whole list (a
263	/// list replaces) or `.some(nil)`, null, which removes it. An action's end
264	/// decodes its `curves` through this type too, so the sub-tab's `◆N` sees
265	/// exactly what an end holds.
266	struct ColorCurvesPatch: Codable, Equatable {
267	    var master: [CurvePoint]??
268	    var red: [CurvePoint]??
269	    var green: [CurvePoint]??
270	    var blue: [CurvePoint]??
271	    var hueHue: [CurvePoint]??
272	    var hueSat: [CurvePoint]??
273	
274	    init(
275	        master: [CurvePoint]?? = nil, red: [CurvePoint]?? = nil,
276	        green: [CurvePoint]?? = nil, blue: [CurvePoint]?? = nil,
277	        hueHue: [CurvePoint]?? = nil, hueSat: [CurvePoint]?? = nil
278	    ) {
279	        self.master = master
280	        self.red = red
281	        self.green = green
282	        self.blue = blue
283	        self.hueHue = hueHue
284	        self.hueSat = hueSat
285	    }
286	
287	    init(from decoder: Decoder) throws {
288	        let c = try decoder.container(keyedBy: CodingKeys.self)
289	        master = c.nullable(.master)
290	        red = c.nullable(.red)
291	        green = c.nullable(.green)
292	        blue = c.nullable(.blue)
293	        hueHue = c.nullable(.hueHue)
294	        hueSat = c.nullable(.hueSat)
295	    }
296	
297	    /// The section's Reset on the base: all six null.
298	    static let reset = ColorCurvesPatch(
299	        master: .some(nil), red: .some(nil), green: .some(nil), blue: .some(nil),
300	        hueHue: .some(nil), hueSat: .some(nil))
301	
302	    /// Reset inside an action: each named channel its domain's identity,
303	    /// which an end keeps as "animate to neutral" (`null` there would remove
304	    /// the key instead).
305	    static func neutral(_ channels: [CurveChannel]) -> ColorCurvesPatch {
306	        var patch = ColorCurvesPatch()
307	        for channel in channels { patch = patch.setting(channel, .some(channel.domain.identity)) }
308	        return patch
309	    }
310	
311	    /// One channel's whole list, or nil to remove it.
312	    static func channel(_ channel: CurveChannel, _ points: [CurvePoint]?) -> ColorCurvesPatch {
313	        ColorCurvesPatch().setting(channel, .some(points))
314	    }
315	
316	    /// This patch with `channel`'s entry replaced: nil leaves the channel
317	    /// out of the write, `.some(nil)` removes it, a list replaces it.
318	    func setting(_ channel: CurveChannel, _ entry: [CurvePoint]??) -> ColorCurvesPatch {
319	        var patch = self
320	        switch channel {
321	        case .master: patch.master = entry
322	        case .red: patch.red = entry
323	        case .green: patch.green = entry
324	        case .blue: patch.blue = entry
325	        case .hueHue: patch.hueHue = entry
326	        case .hueSat: patch.hueSat = entry
327	        }
328	        return patch
329	    }
330	
331	    /// The channel's entry: nil when the write does not name it.
332	    func entry(_ channel: CurveChannel) -> [CurvePoint]?? {
333	        switch channel {
334	        case .master: return master
335	        case .red: return red
336	        case .green: return green
337	        case .blue: return blue
338	        case .hueHue: return hueHue
339	        case .hueSat: return hueSat
340	        }
341	    }
342	
343	    var isEmpty: Bool { CurveChannel.allCases.allSatisfy { entry($0) == nil } }
344	}
345	
346	extension LayerUniforms {
347	    /// The curves' flags (spec §11 GR-12, GR-32): `curvesEnabled` 1 exactly
348	    /// when one of the four tone curves is not the identity, and
349	    /// `hueCurvesEnabled` 1 exactly when a hue curve is not, so a layer
350	    /// without them never enters either half of step 4c.2 and renders
351	    /// byte-identical. The curves themselves travel in the strip at
352	    /// `texture(3)` (`CurveTextures`), not in the block.
353	    mutating func apply(curves: ColorCurves) {
354	        curvesEnabled = curves.toneIsIdentity ? 0 : 1
355	        hueCurvesEnabled = curves.hueIsIdentity ? 0 : 1
356	    }
357	}
