160	/// `video.curves`: the four tone curves and the two hue curves (spec §11
161	/// GR-32), each a list of 2–16 points with x strictly rising. Read
162	/// leniently: an absent, null or malformed channel is its domain's identity,
163	/// as the core writes an absent one. A blended channel (GR-34) holds its
164	/// `from` points, with the blend in `blends`; a malformed blend is the
165	/// identity. `blends` is never encoded.
166	struct ColorCurves: Codable, Hashable {
167	    let master: [CurvePoint]
168	    let red: [CurvePoint]
169	    let green: [CurvePoint]
170	    let blue: [CurvePoint]
171	    let hueHue: [CurvePoint]
172	    let hueSat: [CurvePoint]
173	    /// The channels blended at this instant, each with its two lists and t.
174	    let blends: [CurveChannel: CurveBlend]
175	
176	    private enum CodingKeys: String, CodingKey {
177	        case master, red, green, blue, hueHue, hueSat
178	    }
179	
180	    /// The tone identity's shortest spelling, `[[0, 0], [1, 1]]`.
181	    static let identityCurve = [CurvePoint(x: 0, y: 0), CurvePoint(x: 1, y: 1)]
182	
183	    init(
184	        master: [CurvePoint] = identityCurve, red: [CurvePoint] = identityCurve,
185	        green: [CurvePoint] = identityCurve, blue: [CurvePoint] = identityCurve,
186	        hueHue: [CurvePoint] = CurveDomain.hueShift.identity,
187	        hueSat: [CurvePoint] = CurveDomain.hueGain.identity,
188	        blends: [CurveChannel: CurveBlend] = [:]
189	    ) {
190	        self.master = master
191	        self.red = red
192	        self.green = green
193	        self.blue = blue
194	        self.hueHue = hueHue
195	        self.hueSat = hueSat
196	        self.blends = blends
197	    }
